ST.xhtml:
IF rMin <= rMax THEN
    rLo := rMin;
    rHi := rMax;
ELSE
    rLo := rMax;
    rHi := rMin;
END_IF
F_Clamp := LIMIT(rLo, rIn, rHi);

IF iRaw < 0 OR iRaw > 27648 THEN
    xFault := TRUE;
ELSE
    xFault := FALSE;
    rValue := F_Clamp(rIn := rLo + (rHi - rLo) * INT_TO_REAL(iRaw) / 27648.0, rMin := rLo, rMax := rHi);
END_IF

IF xReset THEN
    rTotal_m3 := 0.0;
ELSIF rFlow_m3h > 0.0 THEN
    rTotal_m3 := rTotal_m3 + rFlow_m3h * TIME_TO_REAL(tCycle) / 3600000.0;
END_IF
diPulses := REAL_TO_DINT(rTotal_m3);

fbTon(IN := xStart, PT := T#150MS);
xQ := fbTon.Q;
tEt := fbTon.ET;

(* cds2ms: MIGRATION-TODO вручную: MS-ST-05 — см. MANUAL_STEPS.md *)
fbScale(iRaw := GVL_IO_iFlowRaw, rLo := 0.0, rHi := 120.0);
fbTotal(rFlow_m3h := fbScale.rValue, tCycle := T#10MS);
GVL_Retain_rTotalDosed := fbTotal.rTotal_m3;
IF eState = E_DoseState.Dosing THEN
    GVL_IO_xPumpOut := TRUE;
END_IF;
IF GVL_IO_xLevelLow THEN
    GVL_IO_xPumpOut := FALSE;
END_IF;
CASE eState OF
    E_DoseState.Idle:
        IF NOT GVL_IO_xLevelLow THEN
            eState := E_DoseState.Priming;
            dtLastStart := DT#1970-01-01-00:00:00;
        END_IF
    E_DoseState.Priming:
        eState := E_DoseState.Dosing;
    E_DoseState.Dosing:
        IF GVL_IO_xLevelLow THEN
            eState := E_DoseState.Idle;
        END_IF
ELSE
    eState := E_DoseState.Fault;
END_CASE
ltUptime := ltUptime + LTIME#10MS;
sMsg := stRecipe.sName;
rLevel := fbScale.rValue;
pRaw := ADR(iStep);
IF iStep > 3 THEN
    JMP lblEnd;
END_IF
iStep := iStep + 1;
lblEnd:
;

(* itfDev := fbPump: интерфейс заменён экземпляром (MS-LANG-06) *)
IF xRun AND NOT fbPump.xRunning THEN
    fbPump(migCall := 1);
    xOk := fbPump.Start_ret;
END_IF;
IF xStop THEN
    fbPump(migCall := 2);
END_IF;
fbPump(rStroke_ml := 0.5);
fbPump(migCall := 3, Dose_rAmount_ml := 0.25, Dose_rTotal_ml := rTotal_ml);
rTotal_ml := fbPump.Dose_rTotal_mlOut;
xOk := fbPump.Dose_ret;
iState := fbPump.State;
iLoops := 0;
WHILE TRUE DO
    fbPump(migCall := 4, NeedsMore_rTarget_ml := 2.0);
    migT1 := fbPump.NeedsMore_ret;
    IF NOT (migT1 AND iLoops < 3) THEN
        EXIT;
    END_IF;
    fbPump(rStroke_ml := 0.5);
    iLoops := iLoops + 1;
END_WHILE;
rPumped_ml := fbPump.Dosed;

(* cds2ms: MS-LANG-06 режим вызова методов *)
IF migCall <> 0 THEN
    CASE migCall OF
        1: (* Start *)
            xRunning := TRUE;
            iState := 1;
            Start_ret := TRUE;
        2: (* Stop *)
            xRunning := FALSE;
            iState := 0;
    END_CASE;
    State := iState;
    migCall := 0;
    RETURN;
END_IF;
IF xRunning THEN
    udiTicks := udiTicks + 1;
END_IF
State := iState;

(* cds2ms: MS-LANG-06 режим вызова методов *)
IF migCall <> 0 THEN
    CASE migCall OF
        1: (* Start *)
            xRunning := TRUE;
            iState := 1;
            Start_ret := TRUE;
        2: (* Stop *)
            xRunning := FALSE;
            iState := 0;
        3: (* Dose *)
            IF xRunning THEN
                Dose_rTotal_ml := Dose_rTotal_ml + Dose_rAmount_ml;
                Dose_ret := TRUE;
            ELSE
                Dose_ret := FALSE;
            END_IF
            Dose_rTotal_mlOut := Dose_rTotal_ml;
        4: (* NeedsMore *)
            NeedsMore_ret := rDosed_ml < NeedsMore_rTarget_ml;
        5: (* Prime *)
            (* Start() встроен *)
            xRunning := TRUE;
            iState := 1;
            Start_ret := TRUE;
            rDosed_ml := 0.0;
    END_CASE;
    State := iState;
    Dosed := rDosed_ml;
    migCall := 0;
    RETURN;
END_IF;
(* SUPER^() *)
IF xRunning THEN
    udiTicks := udiTicks + 1;
END_IF
IF xRunning THEN
    rDosed_ml := rDosed_ml + rStroke_ml;
END_IF
State := iState;
Dosed := rDosed_ml;

(* cds2ms: MS-LANG-01 FBD → ST, сеть 1 *)
xHi := rLevel > rHi;
(* cds2ms: MS-LANG-01 FBD → ST, сеть 2 *)
IF NOT xBypass THEN
    (* cds2ms: MS-LANG-01 FBD → ST, сеть 3 *)
    fbLatch(SET := rLevel > rHiHi, RESET1 := xAck);
    xAlarm := fbLatch.Q1;
END_IF;
(* cds2ms: MS-LANG-01 FBD → ST, сеть 4 *)
xHiHi := rLevel > rHiHi;

(* cds2ms: MS-LANG-01 FBD → ST, сеть 1 *)
IF xInterlock THEN
    RETURN;
END_IF;
(* cds2ms: MS-LANG-01 FBD → ST, сеть 2 *)
fbState(SET1 := xOpenCmd, RESET := xCloseCmd);
xOpen := fbState.Q1;
(* cds2ms: MS-LANG-01 FBD → ST, сеть 3 *)
fbFbDelay(IN := xOpen AND NOT xFbOpen, PT := T#40MS);
xFault := fbFbDelay.Q;
(* cds2ms: MS-LANG-01 FBD → ST, сеть 4 *)
xMonitor := xOpen AND NOT xFbOpen;

(* cds2ms: MS-LANG-02 LD → ST, сеть 1 *)
xPermit := NOT xLowLevel;
(* cds2ms: MS-LANG-02 LD → ST, сеть 2 *)
IF xHighPress THEN
    xTrip := TRUE;
END_IF;
(* cds2ms: MS-LANG-02 LD → ST, сеть 3 *)
IF xReset THEN
    xTrip := FALSE;
END_IF;
(* cds2ms: MS-LANG-02 LD → ST, сеть 4 *)
migTrig4_1(CLK := xStartPb);
IF migTrig4_1.Q AND NOT xTrip AND xPermit THEN
    xRunLatch := TRUE;
END_IF;
(* cds2ms: MS-LANG-02 LD → ST, сеть 5 *)
IF xStopPb OR xTrip THEN
    xRunLatch := FALSE;
END_IF;

(* cds2ms: MS-LANG-02 LD → ST, сеть 1 *)
xPumpCmd := (xAuto AND xPermit) OR xManual;
(* cds2ms: MS-LANG-02 LD → ST, сеть 2 *)
xLamp := xPumpCmd OR xLampTest;
(* cds2ms: MS-LANG-02 LD → ST, сеть 3 *)
migTrig3_1(CLK := xPumpCmd);
xStartPulse := migTrig3_1.Q;
(* cds2ms: MS-LANG-02 LD → ST, сеть 4 *)
iNext := iStarts + 1;
(* cds2ms: MS-LANG-02 LD → ST, сеть 5 *)
iStarts := SEL(xStartPulse, iStarts, iNext);

migCfc1 := rSp - rPv;
migCfc5 := LIMIT(0.0, migCfc5 + (migCfc1 * rKi), 100.0);
rOut := SEL(xEnable, 0.0, LIMIT(0.0, (migCfc1 * rKp) + migCfc5, 100.0));
rErr := migCfc1;

migCfc1 := rFlowA * rRatio;
migCfc4 := migCfc4 + ((migCfc1 - migCfc4) * 0.5);
rFilt := migCfc4;
rFlowBSp := migCfc1;

(* cds2ms: MS-LANG-04 SFC → ST-автомат с порядком обработки CODESYS *)
IF NOT migSfcInit THEN
    migSfcInit := TRUE;
    migS_Init_xn := TRUE;
END_IF;
(* копия _x -> x и время шагов *)
migS_Init_xp := migS_Init_x;
migS_Init_x := migS_Init_xn;
migS_Fill_xp := migS_Fill_x;
migS_Fill_x := migS_Fill_xn;
migS_WaitFill_xp := migS_WaitFill_x;
migS_WaitFill_x := migS_WaitFill_xn;
migS_Heat_xp := migS_Heat_x;
migS_Heat_x := migS_Heat_xn;
migS_WaitHeat_xp := migS_WaitHeat_x;
migS_WaitHeat_x := migS_WaitHeat_xn;
migS_Mix_xp := migS_Mix_x;
migS_Mix_x := migS_Mix_xn;
migS_Done_xp := migS_Done_x;
migS_Done_x := migS_Done_xn;
migS_Init_tmr(IN := migS_Init_x, PT := T#24D);
migS_Init_t := migS_Init_tmr.ET;
migS_Fill_tmr(IN := migS_Fill_x, PT := T#24D);
migS_Fill_t := migS_Fill_tmr.ET;
migS_WaitFill_tmr(IN := migS_WaitFill_x, PT := T#24D);
migS_WaitFill_t := migS_WaitFill_tmr.ET;
migS_Heat_tmr(IN := migS_Heat_x, PT := T#24D);
migS_Heat_t := migS_Heat_tmr.ET;
migS_WaitHeat_tmr(IN := migS_WaitHeat_x, PT := T#24D);
migS_WaitHeat_t := migS_WaitHeat_tmr.ET;
migS_Mix_tmr(IN := migS_Mix_x, PT := T#24D);
migS_Mix_t := migS_Mix_tmr.ET;
migS_Done_tmr(IN := migS_Done_x, PT := T#24D);
migS_Done_t := migS_Done_tmr.ET;
(* блоки управления IEC-действий *)
migA_ActAlarm_q := (migS_Heat_x AND migS_Heat_t >= T#50MS);
migA_ActAlarm_x := migA_ActAlarm_q OR migA_ActAlarm_qp;
migA_ActAlpha_q := migS_Mix_x;
migA_ActAlpha_x := migA_ActAlpha_q OR migA_ActAlpha_qp;
migA_ActCount_q := (migS_Mix_x AND NOT migS_Mix_xp);
migA_ActCount_x := migA_ActCount_q OR migA_ActCount_qp;
migA_ActFill_q := migS_Fill_x;
migA_ActFill_x := migA_ActFill_q OR migA_ActFill_qp;
migA_ActFlush_q := (migS_Fill_x AND migS_Fill_t < T#30MS);
migA_ActFlush_x := migA_ActFlush_q OR migA_ActFlush_qp;
migA_ActHeat_q := migS_Heat_x;
migA_ActHeat_x := migA_ActHeat_q OR migA_ActHeat_qp;
migA_ActMixer_s := (migA_ActMixer_s OR migS_Mix_x) AND NOT (migS_Done_x);
migA_ActMixer_q := migA_ActMixer_s;
migA_ActMixer_x := migA_ActMixer_q OR migA_ActMixer_qp;
migA_ActZeta_q := migS_Heat_x;
migA_ActZeta_x := migA_ActZeta_q OR migA_ActZeta_qp;
(* IEC-действия по алфавиту: проход 1 — последний вызов деактивированных, проход 2 — активные *)
FOR migSfcPass := 1 TO 2 DO
    IF (migSfcPass = 1 AND migA_ActAlarm_qp AND NOT migA_ActAlarm_q) OR (migSfcPass = 2 AND migA_ActAlarm_q) THEN
        xAlarm := migA_ActAlarm_x;
    END_IF;
    IF (migSfcPass = 1 AND migA_ActAlpha_qp AND NOT migA_ActAlpha_q) OR (migSfcPass = 2 AND migA_ActAlpha_q) THEN
        IF migA_ActAlpha_x THEN
            iSeq := (iSeq * 10 + 1) MOD 10000;
        END_IF
    END_IF;
    IF (migSfcPass = 1 AND migA_ActCount_qp AND NOT migA_ActCount_q) OR (migSfcPass = 2 AND migA_ActCount_q) THEN
        IF migA_ActCount_x THEN
            iBatches := iBatches + 1;
        END_IF
    END_IF;
    IF (migSfcPass = 1 AND migA_ActFill_qp AND NOT migA_ActFill_q) OR (migSfcPass = 2 AND migA_ActFill_q) THEN
        xValveIn := migA_ActFill_x;
    END_IF;
    IF (migSfcPass = 1 AND migA_ActFlush_qp AND NOT migA_ActFlush_q) OR (migSfcPass = 2 AND migA_ActFlush_q) THEN
        xFlush := migA_ActFlush_x;
    END_IF;
    IF (migSfcPass = 1 AND migA_ActHeat_qp AND NOT migA_ActHeat_q) OR (migSfcPass = 2 AND migA_ActHeat_q) THEN
        xHeater := migA_ActHeat_x;
    END_IF;
    IF (migSfcPass = 1 AND migA_ActMixer_qp AND NOT migA_ActMixer_q) OR (migSfcPass = 2 AND migA_ActMixer_q) THEN
        xMixer := migA_ActMixer_x;
    END_IF;
    IF (migSfcPass = 1 AND migA_ActZeta_qp AND NOT migA_ActZeta_q) OR (migSfcPass = 2 AND migA_ActZeta_q) THEN
        IF migA_ActZeta_x THEN
            iSeq := (iSeq * 10 + 2) MOD 10000;
        END_IF
    END_IF;
END_FOR;
migA_ActAlarm_qp := migA_ActAlarm_q;
migA_ActAlpha_qp := migA_ActAlpha_q;
migA_ActCount_qp := migA_ActCount_q;
migA_ActFill_qp := migA_ActFill_q;
migA_ActFlush_qp := migA_ActFlush_q;
migA_ActHeat_qp := migA_ActHeat_q;
migA_ActMixer_qp := migA_ActMixer_q;
migA_ActZeta_qp := migA_ActZeta_q;
(* переходы *)
IF migS_Init_x AND migS_Init_xn AND xStart THEN
    migS_Init_xn := FALSE;
    migS_Fill_xn := TRUE;
    migS_Heat_xn := TRUE;
END_IF;
IF migS_Fill_x AND migS_Fill_xn AND xLevelHi THEN
    migS_Fill_xn := FALSE;
    migS_WaitFill_xn := TRUE;
END_IF;
IF migS_Heat_x AND migS_Heat_xn AND xTempOk THEN
    migS_Heat_xn := FALSE;
    migS_WaitHeat_xn := TRUE;
END_IF;
IF migS_WaitFill_x AND migS_WaitFill_xn AND migS_WaitHeat_x AND migS_WaitHeat_xn AND TRUE THEN
    migS_WaitFill_xn := FALSE;
    migS_WaitHeat_xn := FALSE;
    migS_Mix_xn := TRUE;
END_IF;
IF migS_Mix_x AND migS_Mix_xn AND (migS_Mix_t >= T#40MS) THEN
    migS_Mix_xn := FALSE;
    migS_Done_xn := TRUE;
END_IF;
IF migS_Done_x AND migS_Done_xn AND NOT xStart THEN
    migS_Done_xn := FALSE;
    migS_Init_xn := TRUE;
END_IF;

(* cds2ms: MS-LANG-04 SFC → ST-автомат с порядком обработки CODESYS *)
IF NOT migSfcInit THEN
    migSfcInit := TRUE;
    migS_Idle_xn := TRUE;
END_IF;
(* копия _x -> x и время шагов *)
migS_Idle_xp := migS_Idle_x;
migS_Idle_x := migS_Idle_xn;
migS_Acid_xp := migS_Acid_x;
migS_Acid_x := migS_Acid_xn;
migS_Caustic_xp := migS_Caustic_x;
migS_Caustic_x := migS_Caustic_xn;
migS_Rinse_xp := migS_Rinse_x;
migS_Rinse_x := migS_Rinse_xn;
migS_Idle_tmr(IN := migS_Idle_x, PT := T#24D);
migS_Idle_t := migS_Idle_tmr.ET;
migS_Acid_tmr(IN := migS_Acid_x, PT := T#24D);
migS_Acid_t := migS_Acid_tmr.ET;
migS_Caustic_tmr(IN := migS_Caustic_x, PT := T#24D);
migS_Caustic_t := migS_Caustic_tmr.ET;
migS_Rinse_tmr(IN := migS_Rinse_x, PT := T#24D);
migS_Rinse_t := migS_Rinse_tmr.ET;
(* блоки управления IEC-действий *)
migA_ActAcid_q := migS_Acid_x;
migA_ActAcid_x := migA_ActAcid_q OR migA_ActAcid_qp;
migA_ActCaustic_q := migS_Caustic_x;
migA_ActCaustic_x := migA_ActCaustic_q OR migA_ActCaustic_qp;
migA_ActRinseIn_q := (migS_Rinse_x AND NOT migS_Rinse_xp);
migA_ActRinseIn_x := migA_ActRinseIn_q OR migA_ActRinseIn_qp;
migA_ActRinseOut_q := migS_Rinse_x;
migA_ActRinseOut_x := migA_ActRinseOut_q OR migA_ActRinseOut_qp;
(* IEC-действия по алфавиту: проход 1 — последний вызов деактивированных, проход 2 — активные *)
FOR migSfcPass := 1 TO 2 DO
    IF (migSfcPass = 1 AND migA_ActAcid_qp AND NOT migA_ActAcid_q) OR (migSfcPass = 2 AND migA_ActAcid_q) THEN
        xAcidPump := migA_ActAcid_x;
    END_IF;
    IF (migSfcPass = 1 AND migA_ActCaustic_qp AND NOT migA_ActCaustic_q) OR (migSfcPass = 2 AND migA_ActCaustic_q) THEN
        xCausticPump := migA_ActCaustic_x;
    END_IF;
    IF (migSfcPass = 1 AND migA_ActRinseIn_qp AND NOT migA_ActRinseIn_q) OR (migSfcPass = 2 AND migA_ActRinseIn_q) THEN
        IF migA_ActRinseIn_x THEN
            iRinseIn := iRinseIn + 1;
        END_IF
    END_IF;
    IF (migSfcPass = 1 AND migA_ActRinseOut_qp AND NOT migA_ActRinseOut_q) OR (migSfcPass = 2 AND migA_ActRinseOut_q) THEN
        xRinseValve := migA_ActRinseOut_x;
    END_IF;
END_FOR;
migA_ActAcid_qp := migA_ActAcid_q;
migA_ActCaustic_qp := migA_ActCaustic_q;
migA_ActRinseIn_qp := migA_ActRinseIn_q;
migA_ActRinseOut_qp := migA_ActRinseOut_q;
(* переходы *)
IF migS_Idle_x AND migS_Idle_xn AND xAcid THEN
    migS_Idle_xn := FALSE;
    migS_Acid_xn := TRUE;
END_IF;
IF migS_Acid_x AND migS_Acid_xn AND xDone THEN
    migS_Acid_xn := FALSE;
    migS_Rinse_xn := TRUE;
END_IF;
IF migS_Idle_x AND migS_Idle_xn AND xCaustic THEN
    migS_Idle_xn := FALSE;
    migS_Caustic_xn := TRUE;
END_IF;
IF migS_Caustic_x AND migS_Caustic_xn AND xDone THEN
    migS_Caustic_xn := FALSE;
    migS_Rinse_xn := TRUE;
END_IF;
IF migS_Rinse_x AND migS_Rinse_xn AND NOT xDone THEN
    migS_Rinse_xn := FALSE;
    migS_Idle_xn := TRUE;
END_IF;
